104	func NormalizeWindow(since, until time.Time) (time.Time, time.Time) {
105		floored := since.Truncate(time.Minute)
106		ceiled := until.Truncate(time.Minute)
107		if !until.Equal(ceiled) {
108			ceiled = ceiled.Add(time.Minute)
109		}
110		return floored, ceiled
111	}
