8	func RenderMarkdown(dispatch *Dispatch) string {
9		if dispatch == nil {
10			return ""
11		}
12		if dispatch.Generated && strings.TrimSpace(dispatch.GeneratedText) != "" {
13			return strings.TrimSpace(dispatch.GeneratedText) + "\n"
14		}
15	
16		var b strings.Builder
17		b.WriteString("# entire dispatch\n\n")
18		for _, repo := range dispatch.Repos {
19			b.WriteString("## ")
20			b.WriteString(repo.FullName)
21			b.WriteString("\n\n")
22			for _, section := range repo.Sections {
23				b.WriteString("### ")
24				b.WriteString(section.Label)
25				b.WriteString("\n\n")
26				for _, bullet := range section.Bullets {
27					b.WriteString("- ")
28					b.WriteString(bullet.Text)
29					b.WriteString("\n")
30				}
31				b.WriteString("\n")
32			}
33		}
34	
35		fmt.Fprintf(&b, "%d checkpoints · %d used · %d branches · %d files touched\n",
36			dispatch.Totals.Checkpoints,
37			dispatch.Totals.UsedCheckpointCount,
38			dispatch.Totals.Branches,
39			dispatch.Totals.FilesTouched,
40		)
41		appendWarningsMarkdown(&b, dispatch.Warnings)
42		return strings.TrimSpace(b.String()) + "\n"
43	}
44	
45	func appendWarningsMarkdown(b *strings.Builder, warnings Warnings) {
46		lines := warningLines(warnings)
47		if len(lines) == 0 {
48			return
49		}
50		b.WriteString("\n### Warnings\n\n")
51		for _, line := range lines {
52			line = strings.TrimSpace(strings.TrimLeft(line, "⚠⏳✕ℹ "))
53			b.WriteString("- ")
54			b.WriteString(line)
55			b.WriteString("\n")
56		}
57	}
58	
59	func warningLines(warnings Warnings) []string {
60		lines := make([]string, 0, 5)
61		if warnings.AccessDeniedCount > 0 {
62			lines = append(lines, fmt.Sprintf("⚠ %d checkpoints you no longer have access to", warnings.AccessDeniedCount))
63		}
64		if warnings.PendingCount > 0 {
65			lines = append(lines, fmt.Sprintf("⏳ %d checkpoints still being analyzed (retry in a minute)", warnings.PendingCount))
66		}
67		if warnings.FailedCount > 0 {
68			lines = append(lines, fmt.Sprintf("✕ %d checkpoints failed analysis on the server", warnings.FailedCount))
69		}
70		if warnings.UnknownCount > 0 {
71			lines = append(lines, fmt.Sprintf("ℹ %d checkpoints not known to the server", warnings.UnknownCount))
72		}
73		if warnings.UncategorizedCount > 0 {
74			lines = append(lines, fmt.Sprintf("%d uncategorized checkpoints skipped", warnings.UncategorizedCount))
75		}
76		return lines
77	}
