105	func buildDispatchPrompt(dispatch *Dispatch, voice string) (string, error) {
106		if dispatch == nil {
107			dispatch = &Dispatch{}
108		}
109	
110		payload, err := marshalDispatchPromptPayload(dispatch, voice)
111		if err != nil {
112			return "", fmt.Errorf("marshal dispatch prompt payload: %w", err)
113		}
114	
115		sanitizedVoice := sanitizeDispatchVoice(ResolveVoice(voice).Text)
116		if sanitizedVoice == "" {
117			sanitizedVoice = "neutral"
118		}
119	
120		return fmt.Sprintf(`%s
121	
122	Voice preference:
123	<voice_preference>
124	%s
125	</voice_preference>
126	
127	Structured dispatch data:
128	<dispatch_data>
129	%s
130	</dispatch_data>
131	
132	Write the final dispatch in markdown.`, dispatchGenerationSystemPrompt, escapeDispatchPrompt(sanitizedVoice), escapeDispatchPrompt(payload)), nil
133	}
