188	func escapeDispatchPrompt(text string) string {
189		return strings.NewReplacer(
190			"</dispatch_data", "&lt;/dispatch_data",
191			"<dispatch_data", "&lt;dispatch_data",
192			"</voice_preference", "&lt;/voice_preference",
193			"<voice_preference", "&lt;voice_preference",
194		).Replace(text)
195	}
196	
197	func sanitizeDispatchVoice(raw string) string {
198		return strings.Join(strings.Fields(strings.Map(func(r rune) rune {
199			switch {
200			case (r >= 0 && r <= 8) || r == 11 || r == 12 || (r >= 14 && r <= 31) || r == 127:
201				return -1
202			case (r >= 0x200B && r <= 0x200F) || (r >= 0x202A && r <= 0x202E) || (r >= 0x2060 && r <= 0x2069):
203				return -1
204			default:
205				return r
206			}
207		}, raw)), " ")
208	}
