242	func buildDispatchCommand(opts dispatchpkg.Options) string {
243		return strings.Join(compactStrings([]string{
244			"entire dispatch",
245			mapBoolToFlag(opts.Mode == dispatchpkg.ModeLocal, "--local"),
246			renderStringFlag("--since", strings.TrimSpace(opts.Since)),
247			mapBoolToFlag(opts.AllBranches, "--all-branches"),
248			renderStringFlag("--repos", strings.Join(opts.RepoPaths, ",")),
249			renderStringFlag("--org", strings.TrimSpace(opts.Org)),
250			renderStringFlag("--voice", strings.TrimSpace(opts.Voice)),
251		}), " ")
252	}
