458	func discoverDispatchWizardChoices(ctx context.Context) (dispatchWizardChoices, error) {
459		currentRepo, err := paths.WorktreeRoot(ctx)
460		if err != nil {
461			return dispatchWizardChoices{}, fmt.Errorf("not in a git repository: %w", err)
462		}
463	
464		repoSlugs, err := listDispatchWizardRepos(ctx)
465		if err != nil || len(repoSlugs) == 0 {
466			repoSlugs = discoverLocalRepoSlugs(ctx, currentRepo)
467		}
468		sort.Strings(repoSlugs)
469	
470		repoOptions := make([]huh.Option[string], 0, len(repoSlugs))
471		seenRepoSlugs := make(map[string]struct{}, len(repoSlugs))
472		for _, repoSlug := range repoSlugs {
473			if repoSlug == "" {
474				continue
475			}
476			if _, ok := seenRepoSlugs[repoSlug]; ok {
477				continue
478			}
479			seenRepoSlugs[repoSlug] = struct{}{}
480			repoOptions = append(repoOptions, huh.NewOption(repoSlug, repoSlug))
481		}
482	
483		orgNames, err := listDispatchWizardOrgs(ctx)
484		if err != nil {
485			orgNames = nil
486		}
487		sort.Strings(orgNames)
488	
489		orgOptions := make([]huh.Option[string], 0, len(orgNames))
490		for _, org := range orgNames {
491			orgOptions = append(orgOptions, huh.NewOption(org, org))
492		}
493	
494		return dispatchWizardChoices{
495			currentRepo: currentRepo,
496			repoOptions: repoOptions,
497			orgOptions:  orgOptions,
498		}, nil
499	}
