501	func discoverLocalRepoRoots(ctx context.Context, currentRepo string) []string {
502		rootSet := map[string]struct{}{currentRepo: {}}
503		parent := filepath.Dir(currentRepo)
504	
505		entries, err := os.ReadDir(parent)
506		if err == nil {
507			for _, entry := range entries {
508				if !entry.IsDir() {
509					continue
510				}
511				candidate := filepath.Join(parent, entry.Name())
512				repoRoot, resolveErr := resolveGitTopLevel(ctx, candidate)
513				if resolveErr != nil {
514					continue
515				}
516				rootSet[repoRoot] = struct{}{}
517			}
518		}
519	
520		repoRoots := make([]string, 0, len(rootSet))
521		for repoRoot := range rootSet {
522			repoRoots = append(repoRoots, repoRoot)
523		}
524		sort.Slice(repoRoots, func(i, j int) bool {
525			if repoRoots[i] == currentRepo {
526				return true
527			}
528			if repoRoots[j] == currentRepo {
529				return false
530			}
531			return filepath.Base(repoRoots[i]) < filepath.Base(repoRoots[j])
532		})
533		return repoRoots
534	}
535	
536	func discoverLocalRepoSlugs(ctx context.Context, currentRepo string) []string {
537		repoRoots := discoverLocalRepoRoots(ctx, currentRepo)
538		repoSlugs := make([]string, 0, len(repoRoots))
539		seenRepoSlugs := make(map[string]struct{}, len(repoRoots))
540		for _, repoRoot := range repoRoots {
541			repoSlug := discoverRepoSlug(repoRoot)
542			if repoSlug == "" {
543				continue
544			}
545			if _, ok := seenRepoSlugs[repoSlug]; ok {
546				continue
547			}
548			seenRepoSlugs[repoSlug] = struct{}{}
549			repoSlugs = append(repoSlugs, repoSlug)
550		}
551		return repoSlugs
552	}
553	
554	func resolveGitTopLevel(ctx context.Context, path string) (string, error) {
555		cmd := exec.CommandContext(ctx, "git", "-C", path, "rev-parse", "--show-toplevel")
556		output, err := cmd.Output()
557		if err != nil {
558			return "", err
559		}
560		return strings.TrimSpace(string(output)), nil
561	}
562	
563	func discoverBranchOptions(ctx context.Context, repoRoot string) []huh.Option[string] {
564		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "for-each-ref", "--format=%(refname:short)", "refs/heads")
565		output, err := cmd.Output()
566		if err != nil {
567			return nil
568		}
569	
570		lines := strings.Split(strings.TrimSpace(string(output)), "\n")
571		branches := make([]string, 0, len(lines))
572		for _, line := range lines {
573			line = strings.TrimSpace(line)
574			if line != "" && !shouldHideDispatchWizardBranch(line) {
575				branches = append(branches, line)
576			}
577		}
578		sort.Strings(branches)
579	
580		options := make([]huh.Option[string], 0, len(branches))
581		for _, branch := range branches {
582			options = append(options, huh.NewOption(branch, branch))
583		}
584		return options
585	}
586	
587	func shouldHideDispatchWizardBranch(branch string) bool {
588		branch = strings.TrimSpace(branch)
589		return strings.HasPrefix(branch, "entire/")
590	}
