593		cmd := exec.CommandContext(ctx, "gh", "api", "user/orgs", "--jq", ".[].login")
594		output, err := cmd.Output()
595		if err != nil {
596			return nil, err
597		}
598	
599		orgs := make([]string, 0)
600		for _, line := range strings.Split(string(output), "\n") {
601			line = strings.TrimSpace(line)
602			if line != "" {
603				orgs = append(orgs, line)
604			}
605		}
606		sort.Strings(orgs)
