189	func (m dispatchStatusModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
190		switch msg := msg.(type) {
191		case tea.WindowSizeMsg:
192			m.width = msg.Width
193			m.height = msg.Height
194			return m, nil
195		case spinner.TickMsg:
196			var cmd tea.Cmd
197			m.spinner, cmd = m.spinner.Update(msg)
198			return m, cmd
199		case dispatchRenderResult:
200			m.result = msg
201			return m, tea.Quit
202		case tea.KeyMsg:
203			switch msg.String() {
204			case "ctrl+c", "esc", "q":
205				if m.cancel != nil {
206					m.cancel()
207				}
208				m.result.err = errDispatchCancelled
209				return m, tea.Quit
210			}
211		}
212		return m, nil
213	}
