238	func clearDispatchInlineView(w io.Writer, view string) {
239		lineCount := renderedLineCount(view)
240		for range lineCount {
241			_, _ = io.WriteString(w, "\x1b[1A\x1b[2K\r")
242		}
243	}
244	
245	func renderedLineCount(view string) int {
246		if view == "" {
247			return 0
248		}
249		return strings.Count(view, "\n") + 1
250	}
