66		cloud := NewCloudClient(CloudConfig{BaseURL: cloudBaseURL(), Token: token})
67		reqBody := CreateDispatchRequest{
68			Repo:     repoScope,
69			Org:      opts.Org,
70			Since:    since.Format(time.RFC3339),
71			Until:    until.Format(time.RFC3339),
72			Branches: branches,
73			Generate: true,
74			Voice:    opts.Voice,
75		}
76		response, err := cloud.CreateDispatch(ctx, reqBody)
77		if err != nil {
78			return nil, err
79		}
80	
81		dispatch := apiToDispatch(response)
82		dispatch.RequestedGenerate = opts.Generate
83		if strings.TrimSpace(dispatch.GeneratedText) == "" {
84			return nil, errDispatchMissingMarkdown
85		}
86		return dispatch, nil
87	}
