89	func apiToDispatch(response *CreateDispatchResponse) *Dispatch {
90		if response == nil {
91			return &Dispatch{}
92		}
93	
94		repos := make([]RepoGroup, 0, len(response.Repos))
95		for _, repo := range response.Repos {
96			sections := make([]Section, 0, len(repo.Sections))
97			for _, section := range repo.Sections {
98				bullets := make([]Bullet, 0, len(section.Bullets))
99				for _, bullet := range section.Bullets {
100					bullets = append(bullets, Bullet{
101						CheckpointID: bullet.CheckpointID,
102						Text:         bullet.Text,
103						Source:       bullet.Source,
104						Branch:       bullet.Branch,
105						CreatedAt:    parseAPITime(bullet.CreatedAt),
106						Labels:       append([]string(nil), bullet.Labels...),
107					})
108				}
109				sections = append(sections, Section{
110					Label:   section.Label,
111					Bullets: bullets,
112				})
113			}
114			repos = append(repos, RepoGroup{
115				FullName: repo.FullName,
116				Sections: sections,
117			})
118		}
119	
120		generatedText := strings.TrimSpace(response.GeneratedMarkdown)
121		if generatedText == "" {
122			generatedText = strings.TrimSpace(response.GeneratedText)
123		}
124	
125		return &Dispatch{
126			Window: Window{
127				NormalizedSince:   parseAPITime(response.Window.NormalizedSince),
128				NormalizedUntil:   parseAPITime(response.Window.NormalizedUntil),
129				FirstCheckpointAt: parseAPITime(response.Window.FirstCheckpointCreatedAt),
130				LastCheckpointAt:  parseAPITime(response.Window.LastCheckpointCreatedAt),
131			},
132			CoveredRepos:  append([]string(nil), response.CoveredRepos...),
133			Repos:         repos,
134			GeneratedText: generatedText,
135			Generated:     generatedText != "",
136			Totals: Totals{
137				Checkpoints:         response.Totals.Checkpoints,
138				UsedCheckpointCount: response.Totals.UsedCheckpointCount,
139				Branches:            response.Totals.Branches,
140				FilesTouched:        response.Totals.FilesTouched,
141			},
142			Warnings: Warnings{
143				AccessDeniedCount:  response.Warnings.AccessDeniedCount,
144				PendingCount:       response.Warnings.PendingCount,
145				FailedCount:        response.Warnings.FailedCount,
146				UnknownCount:       response.Warnings.UnknownCount,
147				UncategorizedCount: response.Warnings.UncategorizedCount,
148			},
149		}
150	}
151	
152	func parseAPITime(value string) time.Time {
153		if value == "" {
154			return time.Time{}
155		}
156		parsed, err := time.Parse(time.RFC3339, value)
157		if err != nil {
158			return time.Time{}
159		}
160		return parsed
161	}
