15	func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
16		token, err := lookupCurrentToken()
17		if err != nil {
18			return nil, fmt.Errorf("reading credentials: %w", err)
19		}
20		if token == "" {
21			return nil, errors.New("dispatch requires login — run `entire login`")
22		}
23	
24		now := nowUTC()
25		sinceInput := strings.TrimSpace(opts.Since)
26		if sinceInput == "" {
27			sinceInput = "7d"
28		}
29		since, err := ParseSinceAtNow(sinceInput, now)
30		if err != nil {
31			return nil, err
32		}
33		until, err := ParseUntilAtNow(opts.Until, now)
34		if err != nil {
35			return nil, err
36		}
37		if !since.Before(until) {
38			return nil, errors.New("--since must be before --until")
39		}
40	
41		var repoScope any
42		repoFullNames := append([]string(nil), opts.RepoPaths...)
43		if opts.Org == "" && len(repoFullNames) == 0 {
44			repoRoot, err := paths.WorktreeRoot(ctx)
45			if err != nil {
46				return nil, fmt.Errorf("not in a git repository: %w", err)
47			}
48			repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
49			if err != nil {
50				return nil, fmt.Errorf("open repository: %w", err)
51			}
52			repoFullName, err := resolveRepoFullName(repo)
53			if err != nil {
54				return nil, err
55			}
56			repoScope = repoFullName
57		} else if len(repoFullNames) == 1 {
58			repoScope = repoFullNames[0]
59		} else if len(repoFullNames) > 1 {
60			repoScope = repoFullNames
61		}
62	
63		branches := any(opts.Branches)
64		if opts.AllBranches {
65			branches = "all"
66		}
67	
68		cloud := NewCloudClient(CloudConfig{BaseURL: api.BaseURL(), Token: token})
69		reqBody := CreateDispatchRequest{
70			Repo:     repoScope,
71			Org:      opts.Org,
72			Since:    since.Format(time.RFC3339),
73			Until:    until.Format(time.RFC3339),
74			Branches: branches,
75			Generate: true,
76			Voice:    opts.Voice,
77		}
78		response, err := cloud.CreateDispatch(ctx, reqBody)
79		if err != nil {
80			return nil, err
81		}
82	
83		dispatch := apiToDispatch(response)
84		dispatch.RequestedGenerate = opts.Generate
85		if strings.TrimSpace(dispatch.GeneratedText) == "" {
86			return nil, errDispatchMissingMarkdown
87		}
88		return dispatch, nil
89	}
90	
91	func apiToDispatch(response *CreateDispatchResponse) *Dispatch {
92		if response == nil {
93			return &Dispatch{}
94		}
95	
96		repos := make([]RepoGroup, 0, len(response.Repos))
97		for _, repo := range response.Repos {
98			sections := make([]Section, 0, len(repo.Sections))
99			for _, section := range repo.Sections {
100				bullets := make([]Bullet, 0, len(section.Bullets))
101				for _, bullet := range section.Bullets {
102					bullets = append(bullets, Bullet{
103						CheckpointID: bullet.CheckpointID,
104						Text:         bullet.Text,
105						Source:       bullet.Source,
106						Branch:       bullet.Branch,
107						CreatedAt:    parseAPITime(bullet.CreatedAt),
108						Labels:       append([]string(nil), bullet.Labels...),
109					})
110				}
111				sections = append(sections, Section{
112					Label:   section.Label,
113					Bullets: bullets,
114				})
115			}
116			repos = append(repos, RepoGroup{
117				FullName: repo.FullName,
118				Sections: sections,
119			})
120		}
121	
122		generatedText := strings.TrimSpace(response.GeneratedMarkdown)
123		if generatedText == "" {
124			generatedText = strings.TrimSpace(response.GeneratedText)
125		}
126	
127		return &Dispatch{
128			Window: Window{
129				NormalizedSince:   parseAPITime(response.Window.NormalizedSince),
130				NormalizedUntil:   parseAPITime(response.Window.NormalizedUntil),
131				FirstCheckpointAt: parseAPITime(response.Window.FirstCheckpointCreatedAt),
132				LastCheckpointAt:  parseAPITime(response.Window.LastCheckpointCreatedAt),
133			},
134			CoveredRepos:  append([]string(nil), response.CoveredRepos...),
135			Repos:         repos,
136			GeneratedText: generatedText,
137			Generated:     generatedText != "",
138			Totals: Totals{
139				Checkpoints:         response.Totals.Checkpoints,
140				UsedCheckpointCount: response.Totals.UsedCheckpointCount,
141				Branches:            response.Totals.Branches,
142				FilesTouched:        response.Totals.FilesTouched,
143			},
144			Warnings: Warnings{
145				AccessDeniedCount:  response.Warnings.AccessDeniedCount,
146				PendingCount:       response.Warnings.PendingCount,
147				FailedCount:        response.Warnings.FailedCount,
148				UnknownCount:       response.Warnings.UnknownCount,
149				UncategorizedCount: response.Warnings.UncategorizedCount,
150			},
151		}
152	}
153	
154	func parseAPITime(value string) time.Time {
155		if value == "" {
156			return time.Time{}
157		}
158		parsed, err := time.Parse(time.RFC3339, value)
159		if err != nil {
160			return time.Time{}
161		}
162		return parsed
163	}
