103	func NormalizeWindow(since, until time.Time) (time.Time, time.Time) {
104		floored := since.Truncate(time.Minute)
105		ceiled := until.Truncate(time.Minute)
106		if !until.Equal(ceiled) {
107			ceiled = ceiled.Add(time.Minute)
108		}
109		return floored, ceiled
110	}
