112	func resolveRepoRoots(ctx context.Context, repoPaths []string) ([]string, error) {
113		if len(repoPaths) == 0 {
114			repoRoot, err := paths.WorktreeRoot(ctx)
115			if err != nil {
116				return nil, fmt.Errorf("not in a git repository: %w", err)
117			}
118			return []string{repoRoot}, nil
119		}
120	
121		roots := make([]string, 0, len(repoPaths))
122		for _, repoPath := range repoPaths {
123			cmd := exec.CommandContext(ctx, "git", "-C", repoPath, "rev-parse", "--show-toplevel")
124			output, err := cmd.Output()
125			if err != nil {
126				return nil, fmt.Errorf("resolve repo root for %q: %w", repoPath, err)
127			}
128			roots = append(roots, strings.TrimSpace(string(output)))
129		}
130		return roots, nil
131	}
