133	func enumerateRepoCandidates(ctx context.Context, repoRoot string, opts Options, since, until time.Time) ([]candidate, error) {
134		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
135		if err != nil {
136			return nil, fmt.Errorf("open repository %s: %w", repoRoot, err)
137		}
138	
139		repoFullName, err := resolveRepoFullName(repo)
140		if err != nil {
141			return nil, fmt.Errorf("resolve repo name for %s: %w", repoRoot, err)
142		}
143	
144		branches := opts.Branches
145		if len(branches) == 0 && !opts.AllBranches {
146			currentBranch, err := currentBranchName(repo)
147			if err != nil {
148				return nil, err
149			}
150			branches = []string{currentBranch}
151		}
152		branchSet := make(map[string]struct{}, len(branches))
153		for _, branch := range branches {
154			branchSet[branch] = struct{}{}
155		}
156		reachableCheckpointIDs := map[string]struct{}{}
157		if opts.ImplicitCurrentBranch && !opts.AllBranches {
158			reachableCheckpointIDs, err = reachableCheckpointIDsOnHEAD(ctx, repoRoot)
159			if err != nil {
160				return nil, err
161			}
162		}
163	
164		store := checkpoint.NewGitStore(repo)
165		infos, err := store.ListCommitted(ctx)
166		if err != nil {
167			return nil, fmt.Errorf("list committed checkpoints: %w", err)
168		}
169	
170		candidates := make([]candidate, 0, len(infos))
171		for _, info := range infos {
172			if info.CreatedAt.Before(since) || !info.CreatedAt.Before(until) {
173				continue
174			}
175	
176			summary, err := store.ReadCommitted(ctx, info.CheckpointID)
177			if err != nil || summary == nil {
178				continue
179			}
180			if !opts.AllBranches {
181				_, onSelectedBranch := branchSet[summary.Branch]
182				if !onSelectedBranch {
183					if !opts.ImplicitCurrentBranch {
184						continue
185					}
186					if _, reachable := reachableCheckpointIDs[info.CheckpointID.String()]; !reachable {
187						continue
188					}
189				}
190			}
191	
192			localSummary := ""
193			if len(summary.Sessions) > 0 {
194				latestIndex := len(summary.Sessions) - 1
195				if metadata, err := store.ReadSessionMetadata(ctx, info.CheckpointID, latestIndex); err == nil && metadata != nil && metadata.Summary != nil {
196					localSummary = strings.TrimSpace(metadata.Summary.Outcome)
197					if localSummary == "" {
198						localSummary = strings.TrimSpace(metadata.Summary.Intent)
199					}
200				}
201			}
202	
203			commitSubject, _ := findCommitSubjectByCheckpoint(ctx, repoRoot, info.CheckpointID)
204			candidates = append(candidates, candidate{
205				CheckpointID:      info.CheckpointID.String(),
206				RepoFullName:      repoFullName,
207				Branch:            summary.Branch,
208				CreatedAt:         info.CreatedAt,
209				FilesTouched:      append([]string(nil), info.FilesTouched...),
210				CommitSubject:     commitSubject,
211				LocalSummaryTitle: localSummary,
212			})
213		}
214	
215		return candidates, nil
216	}
