234	func resolveRepoFullName(repo *git.Repository) (string, error) {
235		remote, err := repo.Remote("origin")
236		if err != nil {
237			return "", fmt.Errorf("find origin remote: %w", err)
238		}
239		if len(remote.Config().URLs) == 0 {
240			return "", errors.New("origin remote has no URLs configured")
241		}
242	
243		owner, repoName, err := search.ParseGitHubRemote(remote.Config().URLs[0])
244		if err != nil {
245			return "", err
246		}
247		return owner + "/" + repoName, nil
248	}
