261	func findCommitSubjectByCheckpoint(ctx context.Context, repoRoot string, checkpointID checkpointid.CheckpointID) (string, error) {
262		cmd := exec.CommandContext(ctx, "git", "-C", repoRoot, "log", "--all", "--format=%s%x00", "--grep", "Entire-Checkpoint: "+checkpointID.String())
263		output, err := cmd.Output()
264		if err != nil {
265			return "", err
266		}
267		parts := strings.SplitN(string(output), "\x00", 2)
268		if len(parts) == 0 {
269			return "", nil
270		}
271		return strings.TrimSpace(parts[0]), nil
272	}
