369	func lastAt(used []repoBullet) time.Time {
370		var last time.Time
371		for _, item := range used {
372			if item.Bullet.CreatedAt.After(last) {
373				last = item.Bullet.CreatedAt
374			}
375		}
376		return last
377	}
