492	func discoverLocalRepoRoots(ctx context.Context, currentRepo string) []string {
493		rootSet := map[string]struct{}{currentRepo: {}}
494		parent := filepath.Dir(currentRepo)
495	
496		entries, err := os.ReadDir(parent)
497		if err == nil {
498			candidates := make([]string, 0, len(entries))
499			for _, entry := range entries {
500				if !entry.IsDir() {
501					continue
502				}
503				candidate := filepath.Join(parent, entry.Name())
504				if _, statErr := os.Stat(filepath.Join(candidate, ".git")); statErr != nil {
505					continue
506				}
507				candidates = append(candidates, candidate)
508			}
509	
510			resolved := make([]string, len(candidates))
511			var wg sync.WaitGroup
512			wg.Add(len(candidates))
513			for i, candidate := range candidates {
514				go func() {
515					defer wg.Done()
516					if repoRoot, resolveErr := resolveGitTopLevel(ctx, candidate); resolveErr == nil {
517						resolved[i] = repoRoot
518					}
519				}()
520			}
521			wg.Wait()
522			for _, repoRoot := range resolved {
523				if repoRoot != "" {
524					rootSet[repoRoot] = struct{}{}
525				}
526			}
527		}
528	
529		repoRoots := make([]string, 0, len(rootSet))

